code='''def transform(grid):
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(x for row in g for x in row), key=lambda x: sum(row.count(x) for row in g))
    # The colored instruction is the longest straight contiguous non-background run.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] == bg:
                c += 1
                continue
            start = c
            while c < w and g[r][c] != bg:
                c += 1
            if c - start >= 3:
                runs.append((c - start, [(r, k) for k in range(start, c)], (0, 1)))
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] == bg:
                r += 1
                continue
            start = r
            while r < h and g[r][c] != bg:
                r += 1
            if r - start >= 3:
                runs.append((r - start, [(k, c) for k in range(start, r)], (1, 0)))
    _, cells, (dr, dc) = max(runs, key=lambda x: x[0])
    pattern = [g[r][c] for r, c in cells]
    templ = set(cells)
    counts = {}
    for r in range(h):
        for c in range(w):
            if g[r][c] != bg and (r, c) not in templ:
                counts[g[r][c]] = counts.get(g[r][c], 0) + 1
    marker = max(counts, key=counts.get)
    out = [row[:] for row in g]
    center = len(pattern) // 2
    for r in range(h):
        for c in range(w):
            if g[r][c] == marker and (r, c) not in templ:
                for i, color in enumerate(pattern):
                    rr, cc = r + (i - center) * dr, c + (i - center) * dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
    return out
'''
